<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;Before:&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>ly<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
