<span class="line">r <span class="token operator">=</span> ly<span class="token punctuation">.</span>query<span class="token punctuation">(</span><span class="token string">&#39;SELECT * FROM Australia WHERE scalerank &lt; 3 LIMIT 3&#39;</span><span class="token punctuation">)</span></span>
