<span class="line">other <span class="token operator">=</span> gio<span class="token punctuation">.</span>Layer<span class="token punctuation">(</span>data<span class="token operator">=</span><span class="token punctuation">[</span>ly<span class="token punctuation">.</span>get_feature<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span> name<span class="token operator">=</span><span class="token string">&#39;WA&#39;</span><span class="token punctuation">,</span> gtype<span class="token operator">=</span><span class="token string">&#39;Polygon&#39;</span><span class="token punctuation">)</span></span>
